using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Services;[Authorize]public sealed class EditModel(OrcaFacilDbContext db,ICurrentAccountService account,ICurrentUserService user):PageModel{[BindProperty]public Guid Id{get;set;}[BindProperty]public uint Version{get;set;}[BindProperty]public ServiceFormModel Input{get;set;}=new();[BindProperty]public string? PriceChangeReason{get;set;}public async Task<IActionResult> OnGetAsync(Guid id,CancellationToken ct){if(account.AccountId is not Guid accountId)return Forbid();var x=await db.ServiceCatalogItems.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.AccountId==accountId&&!x.IsDeleted,ct);if(x is null)return NotFound();Id=x.Id;Version=x.Version;Input=new(){Name=x.Name,Code=x.Code,Description=x.Description,UnitCode=x.UnitCode,StandardPrice=x.StandardPrice,EstimatedCost=x.EstimatedCost,SuggestedDurationMinutes=x.SuggestedDurationMinutes,InternalNotes=x.InternalNotes,IsFavorite=x.IsFavorite,IsActive=x.IsActive};return Page();}public async Task<IActionResult> OnPostAsync(CancellationToken ct){if(account.AccountId is not Guid accountId)return Forbid();if(!ModelState.IsValid)return Page();var x=await db.ServiceCatalogItems.SingleOrDefaultAsync(x=>x.Id==Id&&x.AccountId==accountId&&!x.IsDeleted,ct);if(x is null)return NotFound();if(x.Version!=Version){ModelState.AddModelError("","Este serviço foi alterado em outra sessão. Recarregue a página.");return Page();}if(x.StandardPrice!=Input.StandardPrice||x.EstimatedCost!=Input.EstimatedCost)db.ServicePriceHistories.Add(new(){AccountId=accountId,ServiceCatalogItemId=x.Id,PreviousPrice=x.StandardPrice,NewPrice=Input.StandardPrice,PreviousCost=x.EstimatedCost,NewCost=Input.EstimatedCost,Reason=PriceChangeReason?.Trim(),ChangedByUserId=user.UserId});x.Name=Input.Name.Trim();x.Code=string.IsNullOrWhiteSpace(Input.Code)?null:Input.Code.Trim();x.Description=Input.Description?.Trim();x.UnitCode=Input.UnitCode;x.StandardPrice=Input.StandardPrice;x.EstimatedCost=Input.EstimatedCost;x.SuggestedDurationMinutes=Input.SuggestedDurationMinutes;x.InternalNotes=Input.InternalNotes?.Trim();x.IsFavorite=Input.IsFavorite;x.IsActive=Input.IsActive;x.Touch();await db.SaveChangesAsync(ct);TempData["Success"]="Serviço atualizado.";return RedirectToPage("Details",new{id=Id});}}
